document.getElementById('deleteCustom').onclick=async()=>{if(!confirm(t('confirmDelete')))return;const old=photoOverrides()[currentId],path=photoPath(old);if(path&&sb&&cloudUser)await sb.storage.from(PHOTO_BUCKET).remove([path]);delete photoUrlCache[currentId];const nextCustom=customRecipes().filter(x=>x.id!==currentId);localStorage.setItem('cookCustom',JSON.stringify(nextCustom));if(cloudState)cloudState.custom_recipes=nextCustom;cloudChanged();setPhotoOverride(currentId,null);closeModal('recipeModal');buildSelects();render()};
