const APP_VERSION='22';
let activeFilters=new Set();
function readJson(key,fallback){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function writeJson(key,val){localStorage.setItem(key,JSON.stringify(val))}
function familyNutrition(r){
  if(r.familyNutrition) return r.familyNutrition;
  const text=(r.familySwap||[]).join(' ').toLowerCase();
  let delta={kcal:0,p:0,c:0,f:0,fiber:0};
  if(text.includes('oves')||text.includes('oat')) delta={kcal:55,p:-10,c:15,f:1,fiber:2};
  else if(text.includes('jogurt')||text.includes('yogurt')) delta={kcal:35,p:-8,c:8,f:1,fiber:0};
  else if(text.includes('vynech')||text.includes('omit')) delta={kcal:-65,p:-17,c:2,f:0,fiber:0};
  const n={kcal:Math.max(40,Math.round(r.kcal+delta.kcal)),p:Math.max(2,Math.round(r.p+delta.p)),c:Math.max(0,Math.round(r.c+delta.c)),f:Math.max(0,Math.round(r.f+delta.f)),fiber:Math.max(0,Math.round((r.fiber||0)+delta.fiber))};
  r.familyNutrition=n; return n;
}
function timeMetrics(r){
  const nums=(String(r.time||'').match(/\d+/g)||[]).map(Number); const active=nums[0]||999;
  const wait=/overnight|přes noc|一晩/i.test(r.time+' '+(r.prep||''))?480:0;
  return {active,total:(nums[nums.length-1]||active)+wait};
}
function recipeSearchText(r){return [r.name,r.flavor,r.kind,...(r.ingredients||[]),...(r.steps||[])].join(' ').toLowerCase()}
function passesFilter(r,key){const n=nutritionFor(r); if(key==='under150')return n.kcal<=150;if(key==='lowcal')return n.kcal<=200;if(key==='highprotein')return n.p>=20;if(key==='protein30')return n.p>=30;if(key==='highfiber')return n.fiber>=7;if(key==='lowcarb')return n.c<=25;if(key==='lowfat')return n.f<=5;if(key==='cheap')return r.cost<=200;if(key==='family')return (r.familySwap||[]).length>0;if(key==='quick')return timeMetrics(r).active<=15;if(key==='mealprep')return !!(r.prep&&r.prep.length>4);return true}
function filtered(){
 let q=document.getElementById('search').value.toLowerCase(),ch=document.getElementById('chapter').value,arr=allRecipes();
 if(view==='favorites')arr=arr.filter(r=>favs().includes(r.id)); if(view==='custom')arr=arr.filter(r=>r.custom);
 arr=arr.filter(r=>(ch==='all'||r.chapter===ch)&&recipeSearchText(r).includes(q));
 for(const f of activeFilters) arr=arr.filter(r=>passesFilter(r,f));
 const so=document.getElementById('sort').value,n=r=>nutritionFor(r);
 const cmp={kcal:(a,b)=>n(a).kcal-n(b).kcal,kcalHigh:(a,b)=>n(b).kcal-n(a).kcal,protein:(a,b)=>n(b).p-n(a).p,proteinLow:(a,b)=>n(a).p-n(b).p,fiber:(a,b)=>n(b).fiber-n(a).fiber,carbs:(a,b)=>n(a).c-n(b).c,fat:(a,b)=>n(a).f-n(b).f,time:(a,b)=>timeMetrics(a).active-timeMetrics(b).active,cost:(a,b)=>a.cost-b.cost,costHigh:(a,b)=>b.cost-a.cost};
 if(cmp[so])arr.sort(cmp[so]); return arr;
}
function updateFilterUI(){
 document.querySelectorAll('.filter-chip').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'?activeFilters.size===0:activeFilters.has(b.dataset.filter)));
 const count=document.getElementById('activeFilterCount'); if(count)count.textContent=activeFilters.size?`${activeFilters.size} ${t('filters')}`:'';
}
function safeText(v){return String(v??'')}
function cookingHistory(){return readJson('cookHistory',[])}
function markRecipeCooked(r){const h=cookingHistory();h.unshift({id:r.id,name:r.name,date:new Date().toISOString()});writeJson('cookHistory',h.slice(0,100));toast(t('markCooked'));renderHistory()}
function renderHistory(){const root=document.getElementById('historyContent');if(!root)return;const h=cookingHistory();root.innerHTML='';if(!h.length){root.textContent=t('noHistory');return}for(const x of h){const d=document.createElement('div');d.className='history-card';const title=document.createElement('b');title.textContent=translateName(x.name);const p=document.createElement('div');p.className='note';p.textContent=`${t('cookedOn')}: ${new Date(x.date).toLocaleDateString(lang==='ja'?'ja-JP':lang==='en'?'en-US':'cs-CZ')}`;d.append(title,p);root.appendChild(d)}}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
// safer custom recipe fields on render: sanitize all user-originated strings before saving
const originalCustomRecipes=customRecipes;
customRecipes=function(){return originalCustomRecipes().map(r=>r.custom?{...r,name:safeText(r.name),ingredients:(r.ingredients||[]).map(safeText),steps:(r.steps||[]).map(safeText)}:r)};

