  const oldPassesFilter=passesFilter;
  passesFilter=function v15PassesFilter(recipe,key){
    const text=recipeSearchText(recipe);
    if(key==='okara') return /okara|おから/i.test(text);
    if(key==='tofu') return /tofu|豆腐/i.test(text);
    if(key==='soy') return /natto|nattó|納豆|edamame|枝豆|miso|味噌|sój|soy|豆乳/i.test(text);
    return oldPassesFilter(recipe,key);
  };

