    root.innerHTML = `<div class="fs-status-icon">${icon}</div><div class="fs-status-copy"><small>${esc(tr('fsTitle'))}</small><strong>${esc(title)}</strong>${detail ? `<p>${esc(detail)}</p>` : ''}${fatSecretState.ip ? `<code>${esc(fatSecretState.ip)}</code>` : ''}${checked ? `<time>${esc(checked)}</time>` : ''}</div><div class="fs-status-actions">${statusCopyButton(fatSecretState.ip)}<button type="button" class="btn ${fatSecretState.kind === 'connected' ? '' : 'primary'}" id="fatsecretStatusTest">${esc(fatSecretState.kind === 'untested' ? tr('fsTest') : tr('fsRetry'))}</button></div>`;
    root.querySelector('#fatsecretStatusTest')?.addEventListener('click', testFatSecretConnection);
