let v22Scale=1;
function scaleNumberInLine(line,factor){return String(line).replace(/(^|\s)(\d+(?:[.,]\d+)?|\d+\/\d+)(?=\s*(?:g|kg|ml|l|lžič|lžíc|tsp|tbsp|vejce|egg|kus|ks|個|本))/gi,(m,prefix,num)=>{let n;if(num.includes('/')){const [a,b]=num.split('/').map(Number);n=a/b}else n=Number(num.replace(',','.'));const out=Math.round(n*factor*10)/10;return prefix+(Number.isInteger(out)?out:String(out).replace('.',','))});}
