function renderScaleBox(recipe){const old=document.getElementById('v22ScaleBox');old?.remove();const macrosRoot=document.getElementById('mMacros');if(!macrosRoot)return;const n=nutritionFor(recipe), servings=Math.max(1,Number(recipe.servings)||1), total={kcal:Math.round(n.kcal*servings*v22Scale),p:Math.round(n.p*servings*v22Scale*10)/10,c:Math.round(n.c*servings*v22Scale*10)/10,f:Math.round(n.f*servings*v22Scale*10)/10,fiber:Math.round((n.fiber||0)*servings*v22Scale*10)/10};const box=document.createElement('section');box.id='v22ScaleBox';box.className='v22-scale-box';box.innerHTML=`<div class="v22-scale-head"><b>${escapeHtml(t('batchScale'))}</b><span>${escapeHtml(t('yieldLabel'))}: ${Math.round((recipe.yieldCount||servings)*v22Scale*10)/10} ${escapeHtml(recipe.yieldUnit||t('portionsShort'))}</span></div><div class="v22-scale-buttons">${[.5,1,2].map(x=>`<button type="button" class="btn ${v22Scale===x?'primary':''}" data-v22-scale="${x}">${x}×</button>`).join('')}</div><div class="v22-batch"><b>${escapeHtml(t('batchTotal'))}</b><span>${total.kcal} kcal · ${total.p} g B · ${total.c} g S · ${total.f} g T · ${total.fiber} g vlákn.</span></div>${recipe.nutritionNote?`<div class="v22-quality">⚠ ${escapeHtml(recipe.nutritionNote)}</div>`:''}`;macrosRoot.after(box);box.querySelectorAll('[data-v22-scale]').forEach(b=>b.onclick=()=>{v22Scale=Number(b.dataset.v22Scale);renderScaleBox(recipe);renderScaledIngredients(recipe)});}
function renderScaledIngredients(recipe){const root=document.getElementById('mIngredients');if(!root)return;const ingredients=effectiveIngredients(recipe,family);root.innerHTML=ingredients.map((line,i)=>`<li class="ingredient-nutrition"><div class="ingredient-main"><input type="checkbox" data-ing="${i}"><div><div class="ingredient-name">${escapeHtml(trLine(scaleNumberInLine(line,v22Scale)))}</div></div></div></li>`).join('');}
