// Extend filter system with useful v22 tags.
const oldPassesFilter=passesFilter;passesFilter=function(r,key){if(key==='freezer')return (r.tags||[]).includes('mrazák');if(key==='under5')return (r.tags||[]).includes('do 5 minut');if(key==='microwave')return (r.tags||[]).includes('mikrovlnka');if(key==='nobake')return (r.tags||[]).includes('bez pečení');if(key==='postworkout')return (r.tags||[]).includes('po tréninku');return oldPassesFilter(r,key)};
