function normalizeRecipe(r){return (r.ingredients||[]).map(x=>String(x).toLowerCase().replace(/\d+(?:[.,]\d+)?|\s+/g,'').replace(/[^a-zá-ž一-龯ぁ-んァ-ン]/gi,'')).filter(Boolean).sort().join('|')}
function duplicateCandidates(name,ingredients,id){const probe={ingredients};const sig=normalizeRecipe(probe);const nameN=String(name).toLowerCase().replace(/[^a-zá-ž0-9]/gi,'');return allRecipes().filter(r=>Number(r.id)!==Number(id)).map(r=>{const rs=normalizeRecipe(r);const a=new Set(sig.split('|')),b=new Set(rs.split('|'));const overlap=[...a].filter(x=>b.has(x)).length/Math.max(1,new Set([...a,...b]).size);const rn=String(r.name).toLowerCase().replace(/[^a-zá-ž0-9]/gi,'');return {r,score:Math.max(overlap,nameN&&rn.includes(nameN)?1:0)}}).filter(x=>x.score>=.65).sort((a,b)=>b.score-a.score).slice(0,3)}
