function hasCzech(v){return /[áčďéěíňóřšťúůýž]/i.test(String(v));}
function englishFallback(value){let out=String(value);for(const [re,to] of EN_REPL)out=out.replace(re,to);return out;}
const prevV27TrLine=trLine;
trLine=function(value){
  if(lang==='cs')return value;
  const exact=V27_EXACT[String(value)];if(exact)return exact[lang]||value;
  let out=prevV27TrLine(value);
  if(!hasCzech(out))return out;
  const en=englishFallback(out);
  if(lang==='en')return en;
  // Never show Czech in Japanese mode. English is used only when a Japanese exact translation is not available.
  return hasCzech(en)?String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,''):en;
};

function v27Label(cs,en,ja){return lang==='ja'?ja:lang==='en'?en:cs;}
showCookStep=function(){const r=currentRecipe();if(!r)return;const steps=r.steps||[];cookIndex=Math.max(0,Math.min(cookIndex,steps.length-1));document.getElementById('cookCounter').textContent=`${v27Label('Krok','Step','手順')} ${cookIndex+1} ${v27Label('z','of','/')} ${steps.length}`;document.getElementById('cookStep').textContent=trLine(steps[cookIndex]||'');document.getElementById('cookProgress').style.width=`${steps.length?((cookIndex+1)/steps.length)*100:0}%`;document.getElementById('cookPrev').disabled=cookIndex===0;document.getElementById('cookNext').textContent=cookIndex===steps.length-1?v27Label('Hotovo ✓','Done ✓','完了 ✓'):v27Label('Další →','Next →','次へ →');};

